/** Parse a bracket class, starting just after its `[`. */
function parseBracket(text, start) {
  let index = start
  let negated = false
  if (text[index] === '!' || text[index] === '^') {
    negated = true
    index += 1
  }
  const items = []
  let first = true
  for (;;) {
    if (index >= text.length) throw new GlobError('unterminated bracket in pattern')
    if (text[index] === ']' && !first) {
      index += 1
      return { node: { type: 'class', negated, items }, index }
    }
    first = false
    let from
    if (text[index] === '\\') {
      if (index + 1 >= text.length) throw new GlobError('trailing backslash in pattern')
      from = text[index + 1]
      index += 2
    } else {
      from = text[index]
      index += 1
    }
    if (text[index] === '-' && index + 1 < text.length && text[index + 1] !== ']') {
      index += 1
      let to
      if (text[index] === '\\') {
        if (index + 1 >= text.length) throw new GlobError('trailing backslash in pattern')
        to = text[index + 1]
        index += 2
      } else {
        to = text[index]
        index += 1
      }
      items.push({ from, to })
    } else {
      items.push({ from, to: from })
    }
  }
}

